}

main {
  width: 100%;
}

.container {
  max-width: 500px;
  margin: 0 auto;
  background: white;
  border-radius: 12px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
  padding: 2.5rem 2rem;
  animation: slideUp 0.3s ease-out;
}

@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

h1 {
  font-size: 1.75rem;
  font-weight: 600;
  margin-bottom: 1.5rem;
  color: #1a1a1a;
}

form {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

input[type="checkbox"] {
  width: 20px;
  height: 20px;
  margin-right: 0.75rem;
  accent-color: #0066cc;
  cursor: pointer;
  flex-shrink: 0;
}

label {
  display: flex;
  align-items: flex-start;
  cursor: pointer;
  font-size: 1rem;
  color: #1a1a1a;
  font-weight: 500;
}

label a {
  color: #0066cc;
  text-decoration: underline;
  transition: color 0.2s ease;
}

label a:hover {
  color: #0052a3;
}

label a:focus {
  outline: 2px solid #0066cc;
  outline-offset: 2px;
  border-radius: 2px;
}

label span[aria-hidden="true"] {
  color: #d32f2f;
  margin-left: 0.25rem;
}

.helper-text {
  font-size: 0.875rem;
  color: #666;
  margin-left: 2.75rem;
  line-height: 1.5;
}

.error-text {
  font-size: 0.875rem;
  color: #d32f2f;
  margin-left: 2.75rem;
  line-height: 1.5;
  font-weight: 500;
}

.btn-primary {
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  color: white;
  background: linear-gradient(135deg, #0066cc 0%, #0052a3 100%);
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 2px 8px rgba(0, 102, 204, 0.2);
  margin-top: 0.5rem;
}

.btn-primary:hover {
  background: linear-gradient(135deg, #0052a3 0%, #003d7a 100%);
  box-shadow: 0 4px 12px rgba(0, 102, 204, 0.3);
}

.btn-primary:active {
  transform: translateY(1px);
  box-shadow: 0 2px 6px rgba(0, 102, 204, 0.2);
}

.btn-primary:focus {
  outline: 2px solid #0066cc;
  outline-offset: 2px;
}

input[type="checkbox"]:focus + label,
input[type="checkbox"]:focus-visible + label {
  outline: 2px solid #0066cc;
  outline-offset: 2px;
  border-radius: 4px;
}

input[type="checkbox"][aria-invalid="true"] {
  border: 2px solid #d32f2f;
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 1.5rem 1rem;
  }

  h1 {
    font-size: 1.5rem;
    margin-bottom: 1rem;
  }

  input[type="checkbox"] {
    width: 18px;
    height: 18px;
  }

  label {
    font-size: 0.95rem;
  }

  .btn-primary {
    padding: 0.625rem 1.25rem;
    font-size: 0.95rem;
  }
}

@supports (forced-color-adjust: none) {
  input[type="checkbox"] {
    forced-color-adjust: none;
    border: 2px solid ButtonText;
  }

  input[type="checkbox"]:checked {
    background: ButtonText;
    border-color: ButtonText;
  }

  .btn-primary {
    forced-color-adjust: none;
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonText;
  }

  .btn-primary:focus {
    outline: 2px solid ButtonText;
  }

  label a {
    color: LinkText;
  }
}
